insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('a58c6c61-67be-4966-96eb-79c714935836', '93ba51fd-ec93-469a-a58e-27c67497ce68', $$f(x) = √(3x + 6); P(1, 3) op de grafiek; lijn k raakt in P; figuur 1$$,
   $$wiskunde-b-havo-2026-ii-door-punt-p-context1.png$$,
   $$De functie f is gegeven door f(x) = √(3x + 6)
Op de grafiek van f ligt het punt P(1, 3).
Lijn k raakt de grafiek van f in punt P. Zie figuur 1.
figuur 1$$, 'inline'),
  ('fa5e2c3e-4441-4890-bb68-22b28c4940ea', '93ba51fd-ec93-469a-a58e-27c67497ce68', $$parabool g met top in het randpunt van f; g snijdt f in P(1, 3); figuur 2$$,
   $$wiskunde-b-havo-2026-ii-door-punt-p-context2.png$$,
   $$De grafiek van de functie g is een parabool. De top van deze parabool valt samen met het randpunt van de grafiek van f.
De grafiek van g snijdt de grafiek van f in het punt P(1, 3). Zie figuur 2.
figuur 2$$, 'inline'),
  ('56e0653b-6834-4fc7-97b1-507e8ac03566', 'ebb0b6c0-fc21-49ae-be74-4b73ae70855b', $$f(x) = 2½·sin(½x); figuur 1 met nulpunten O, A, B, C; D en E met y-coördinaat 1¼√3; OA is een aantal keer DE$$,
   $$wiskunde-b-havo-2026-ii-twee-sinusoiden-context1.png$$,
   $$De functie f is gegeven door f(x) = 2½·sin(½x)
De grafiek van f is een sinusoïde. In figuur 1 is vanaf de oorsprong O anderhalve periode van deze sinusoïde getekend.
figuur 1
De sinusoïde snijdt de x-as achtereenvolgens in de punten O, A, B en C. Deze punten liggen op de evenwichtsstand van de sinusoïde.
De punten D en E met y-coördinaat 1¼√3 liggen op de sinusoïde zoals aangegeven in figuur 1.
Lijnstuk OA is een aantal keer zo lang als lijnstuk DE.$$, 'inline'),
  ('abec4c7e-2bcf-4a83-92a9-39cad61d006c', 'ebb0b6c0-fc21-49ae-be74-4b73ae70855b', $$figuur 2: f en gestippelde sinusoïde g tussen O en C (opeenvolgende punten op de evenwichtsstand van g)$$,
   $$wiskunde-b-havo-2026-ii-twee-sinusoiden-context2.png$$,
   $$In figuur 2 is opnieuw de grafiek van f tussen de punten O en C getekend.
Tussen de punten O en C is de grafiek van een functie g gestippeld weergegeven. Deze grafiek is een deel van een sinusoïde. De punten O en C zijn twee opeenvolgende punten op de evenwichtsstand van deze sinusoïde.
figuur 2$$, 'inline'),
  ('ff2c1dad-87b9-46b2-b6d8-cd18a94fe912', 'ebb0b6c0-fc21-49ae-be74-4b73ae70855b', $$f en g hebben in O dezelfde helling 1,25; g(x) = v·sin(⅙x); helling benaderen met differentiequotiënt Δy/Δx$$,
   $$wiskunde-b-havo-2026-ii-twee-sinusoiden-context3.png$$,
   $$In O hebben de grafieken van f en g dezelfde helling. Deze helling is gelijk aan 1,25.
Een functievoorschrift van g is van de vorm g(x) = v·sin(⅙x)
De helling van de grafiek van g in O kan benaderd worden door de berekening van het differentiequotiënt Δy/Δx op een klein interval.$$, 'inline'),
  ('9c1be35f-7f1e-40bc-870a-dffe0fc5f585', '3d28d058-b91e-4f6e-b61e-a81e77b17249', $$A(25, 0); cirkel c met middellijn OA en middelpunt M; figuur 1; c: y² = 25x − x²$$,
   $$wiskunde-b-havo-2026-ii-raaklijn-door-een-punt-aan-een-cirkel-context1.png$$,
   $$Gegeven is het punt A(25, 0). Daarbij is de cirkel c gegeven met middellijn OA. Het middelpunt van c is M. Zie figuur 1.
figuur 1
Een vergelijking van c is y² = 25x − x².$$, 'inline'),
  ('f34e78ab-858b-4efc-b0f7-81137d8ea220', '3d28d058-b91e-4f6e-b61e-a81e77b17249', $$cirkel d: y² = 225 − x² met middelpunt O; snijpunten P en Q van c en d; lijn k door A en Q; figuur 2$$,
   $$wiskunde-b-havo-2026-ii-raaklijn-door-een-punt-aan-een-cirkel-context2.png$$,
   $$Verder is de cirkel d gegeven met middelpunt O.
Een vergelijking van d is y² = 225 − x².
De punten P en Q zijn de snijpunten van c en d.
Punt P ligt boven de x-as en punt Q onder de x-as. De lijn k gaat door de punten A en Q. Zie figuur 2.
figuur 2
Punten P en Q hebben dezelfde x-coördinaat. Deze x-coördinaat kun je berekenen door het oplossen van de vergelijking 25x − x² = 225 − x².$$, 'inline'),
  ('7db75838-6b88-4a81-a6c1-e329c02bf9c9', '61e7b36d-2b13-473f-bdf7-a8b2befc39f1', $$parabool f met punten A (x = 2) en B (x = 6); hellingen van de raaklijnen −½ in A en 3½ in B; figuur$$,
   $$wiskunde-b-havo-2026-ii-twee-punten-op-een-parabool-context1.png$$,
   $$De grafiek van f is een parabool. De punten A en B liggen op de grafiek. Zie de figuur.
figuur
Punt A heeft x-coördinaat 2 en punt B heeft x-coördinaat 6.
In punt A is de helling van de raaklijn −½
In punt B is de helling van de raaklijn 3½$$, 'inline'),
  ('ba2e98f0-064a-4a3a-b3e4-bb502c76ea9c', '61e7b36d-2b13-473f-bdf7-a8b2befc39f1', $$f(x) = cx² + dx; stelsel 4c + d = −½ en 12c + d = 3½$$,
   $$wiskunde-b-havo-2026-ii-twee-punten-op-een-parabool-context2.png$$,
   $$Het functievoorschrift van f is van de vorm f(x) = cx² + dx
Uit de bovenstaande gegevens volgt het volgende stelsel:
4c + d = −½
12c + d = 3½$$, 'inline'),
  ('ce61d108-c3ff-4526-85e0-d345046faec8', '61e7b36d-2b13-473f-bdf7-a8b2befc39f1', $$c en d volgen uit het stelsel; A en B lijken even ver van de x-as te liggen$$,
   $$wiskunde-b-havo-2026-ii-twee-punten-op-een-parabool-context3.png$$,
   $$Door het stelsel op te lossen, krijg je de waarden c en d van de functie f.
De punten A en B lijken in de figuur even ver van de x-as te liggen.$$, 'inline'),
  ('76be05b9-12ad-44bc-b1be-2f8a4a028158', '4b99124d-b126-4372-99f3-95e0d8e28349', $$tekenrobot met tekenarm OB = 10 cm en BP = 5 cm; hoek β tussen OB en BP; figuur 1 en figuur 2$$,
   $$wiskunde-b-havo-2026-ii-tekenrobot-context1.png$$,
   $$Een tekenrobot is een apparaat dat zelf kan tekenen. In deze opgave wordt een tekenrobot met een scharnierbare tekenarm bekeken. De tekenarm bestaat uit de beweegbare delen OB en BP. Zie figuur 1.
figuur 1
In figuur 2 is in een assenstelsel een bovenaanzicht weergegeven van de scharnierbare tekenarm. De lengte van OB is 10 cm en de lengte van BP is 5 cm.
De oorsprong is een vast punt. De tekenarm draait om dit punt. In punt B scharniert de tekenarm, waardoor BP om punt B kan draaien. De delen OB en BP maken een hoek β met elkaar.
figuur 2 bovenaanzicht tekenarm$$, 'inline'),
  ('e925057d-9bf8-44da-9f7c-04bb9c660ec4', '4b99124d-b126-4372-99f3-95e0d8e28349', $$P tekent cirkelboog met middelpunt O bij vaste β; gewenste straal 14 cm$$,
   $$wiskunde-b-havo-2026-ii-tekenrobot-context2.png$$,
   $$De tekenrobot tekent met punt P. Om een deel van een cirkel met middelpunt O te tekenen, moet hoek β op een vaste waarde worden ingesteld. Door de tekenarm vervolgens rond de oorsprong te draaien, tekent punt P de cirkelboog. De straal OP van de getekende cirkelboog hangt af van hoek β .
Er moet een cirkelboog met middelpunt O en straal 14 cm worden getekend.$$, 'inline'),
  ('e422d8e2-bdfb-40bf-bffc-d6d834c29405', '4b99124d-b126-4372-99f3-95e0d8e28349', $$andere tekenrobot met OB = BP = 10; R met OR = 20 en hoek 50° met positieve x-as; figuur 3$$,
   $$wiskunde-b-havo-2026-ii-tekenrobot-context3.png$$,
   $$Bij een andere tekenrobot hebben de twee beweegbare delen van de tekenarm allebei lengte 10 cm, dus OB = BP = 10.
Een punt R wordt in het assenstelsel geplaatst zodat lijnstuk OR een hoek van 50 graden maakt ten opzichte van de positieve x-as. Zie figuur 3.
figuur 3
De afstand van punt R tot de oorsprong is 20 cm.
De tekenrobot moet lijnstuk OR gaan tekenen. Hij beweegt daarom punt P in een rechte lijn van O naar R.$$, 'inline'),
  ('316dcdc0-a972-4855-ba7a-bb5d4e01e75c', '4b99124d-b126-4372-99f3-95e0d8e28349', $$figuur 4: tekenarm tijdens het tekenen van lijnstuk OR (momenten a t/m e)$$,
   $$wiskunde-b-havo-2026-ii-tekenrobot-context4.png$$,
   $$In figuur 4 is voor verschillende momenten (a, b, c, d en e) het bovenaanzicht van de tekenarm weergegeven tijdens het tekenen. In de beginstand liggen beide delen van de tekenarm op elkaar en staan ze loodrecht op lijnstuk OR. Punt P bevindt zich in de oorsprong.
figuur 4 bovenaanzicht tekenarm tijdens het tekenen van lijnstuk OP$$, 'inline'),
  ('1a89380f-6c1f-4f79-9e19-1c73773ee55d', '4b99124d-b126-4372-99f3-95e0d8e28349', $$α is hoek van OB met positieve x-as, neemt af tot 50°; in figuur 4c is α = 90°$$,
   $$wiskunde-b-havo-2026-ii-tekenrobot-context5.png$$,
   $$De hoek die lijnstuk OB maakt met de positieve x-as, is aangegeven met α . In eerste instantie is hoek α groter dan 90 graden. Tijdens het tekenen van de lijn wordt hoek α steeds kleiner tot uiteindelijk 50 graden.
In de situatie van figuur 4c geldt dat α = 90°.$$, 'inline'),
  ('bccce678-2c8b-49b6-99e7-fb5ed126e250', '4b99124d-b126-4372-99f3-95e0d8e28349', $$OR ingevoerd met lengte 20 cm en richtingscoëfficiënt 2; figuur 5$$,
   $$wiskunde-b-havo-2026-ii-tekenrobot-context6.png$$,
   $$Om de positie van een willekeurig punt R vast te leggen moeten de helling en lengte van lijnstuk OR in de tekenrobot worden ingevoerd.
Lijnstuk OR wordt ingevoerd met lengte 20 cm en richtingscoëfficiënt 2. In figuur 5 is de eindpositie van de tekenarm van de tekenrobot getekend.
figuur 5$$, 'inline'),
  ('25da64d7-faaa-40eb-8795-2ce36a876b4e', '2a07d3db-f88d-4ccd-bf76-6e89cb46245c', $$f(x) = 2·(½)¹⁻²ˣ; 2 naar rechts en vermenigvuldigen t.o.v. x-as met 8/3 geeft g(x) = (1/6)·4ˣ$$,
   $$wiskunde-b-havo-2026-ii-exponentiele-functies-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 2·(½)¹⁻²ˣ.
De grafiek van f wordt eerst 2 naar rechts verschoven en daarna vermenigvuldigd ten opzichte van de x-as met 8/3.
Zo ontstaat de grafiek van de functie g.
Deze functie kan worden geschreven als g(x) = (1/6)·4ˣ.$$, 'inline'),
  ('f39432b8-2fdb-4715-8b2e-20a2afc6e4ce', '2a07d3db-f88d-4ccd-bf76-6e89cb46245c', $$S op g met y-coördinaat 5; P op g met halve afstand tot de y-as; y-coördinaat van P is (1/6)√30; figuur$$,
   $$wiskunde-b-havo-2026-ii-exponentiele-functies-context2.png$$,
   $$Op de grafiek van g ligt een punt S met y-coördinaat 5.
Op de grafiek van g ligt ook een punt P zó, dat de afstand van P tot de y-as de helft is van de afstand van S tot de y-as. Zie de figuur.
figuur
De y-coördinaat van P is te schrijven als (1/6)√30$$, 'inline'),
  ('d722acec-a3a0-445f-8919-e57a5b179fb6', '1846f41e-6ac0-4b0b-9aef-7f962468766c', $$f(x) = x³ − 6x² + 9x met één maximum en één minimum$$,
   $$wiskunde-b-havo-2026-ii-product-van-functies-context1.png$$,
   $$De functie f is gegeven door f(x) = x³ − 6x² + 9x.
Deze functie heeft één maximum en één minimum.$$, 'inline'),
  ('068384ca-7788-4dff-87c4-eb3b82d97868', '1846f41e-6ac0-4b0b-9aef-7f962468766c', $$f snijdt x-as bij x = 0 en x = 3; h(x) = x² − 2x − 1; v(x) = (x³ − 6x² + 9x)·(x² − 2x − 1); figuur 1; v heeft vier punten gemeenschappelijk met de x-as$$,
   $$wiskunde-b-havo-2026-ii-product-van-functies-context2.png$$,
   $$De grafiek van f heeft twee gemeenschappelijke punten met de x-as, bij x = 0 en x = 3.
Verder is gegeven de functie h(x) = x² − 2x − 1.
De functie f wordt vermenigvuldigd met de functie h. Zo ontstaat de functie v(x) = (x³ − 6x² + 9x)·(x² − 2x − 1).
Zie figuur 1.
figuur 1
De grafiek van v heeft vier punten gemeenschappelijk met de x-as.$$, 'inline'),
  ('c94f9fb4-886c-4f78-8c2f-7bd0bfbc572b', '1846f41e-6ac0-4b0b-9aef-7f962468766c', $$v heeft vier toppen; lijn y = p heeft 1 t/m 5 punten gemeenschappelijk met v; figuur 2 en figuur 3$$,
   $$wiskunde-b-havo-2026-ii-product-van-functies-context3.png$$,
   $$De grafiek van v heeft vier toppen.
De horizontale lijn met vergelijking y = p heeft 1, 2, 3, 4 of 5 punten gemeenschappelijk met de grafiek van v. Het aantal gemeenschappelijke punten hangt af van de waarde van p.
In figuur 2 zie je een voorbeeld waarin de vergelijking y = p vier punten gemeenschappelijk heeft met de grafiek van v.
In figuur 3 zijn voor twee verschillende waarden van p voorbeelden gegeven waarin de lijn y = p drie punten gemeenschappelijk heeft met de grafiek van v.
figuur 2 | figuur 3$$, 'inline'),
  ('2af67f8e-1b2f-45b3-9ae5-6fb87413c0d6', 'e4ece13c-13a3-4935-9044-1e6afeff400e', $$toenamediagram verkochte nieuwe auto's in januari t/m maart 2015 (afgerond op duizendtallen); figuur; februari 31,25% minder dan januari$$,
   $$wiskunde-b-havo-2026-ii-autos-in-nederland-context1.png$$,
   $$Niet op elk moment in het jaar worden er evenveel nieuwe auto’s verkocht. Meestal worden de meeste nieuwe auto’s in januari verkocht.
In een toenamediagram kan de toename of afname van het verkochte aantal nieuwe auto’s per maand ten opzichte van de maand ervoor worden getoond. In de figuur is het toenamediagram gegeven van de aantallen verkochte nieuwe auto’s in de eerste drie maanden van het jaar 2015. De aantallen auto’s zijn afgerond op duizendtallen.
figuur
Verder is bekend dat er in de maand februari 31,25% minder nieuwe auto’s zijn verkocht dan in januari.$$, 'inline'),
  ('b3b2855b-6498-4938-9d12-6a0695044c76', 'e4ece13c-13a3-4935-9044-1e6afeff400e', $$totaal aantal auto's lineair: 5,2 miljoen op 1-1-1990 en 8,1 miljoen op 1-1-2016$$,
   $$wiskunde-b-havo-2026-ii-autos-in-nederland-context2.png$$,
   $$Tussen 1990 en 2016 is het totale aantal auto’s in Nederland bij benadering lineair gegroeid: − Op 1 januari 1990 waren er in totaal 5,2 miljoen auto’s. − Op 1 januari 2016 was dit totale aantal 8,1 miljoen.$$, 'inline'),
  ('cc0e4a46-379d-4184-b929-4992b99eb7d4', 'e4ece13c-13a3-4935-9044-1e6afeff400e', $$elektrische auto's exponentieel: 40 duizend op 1-1-2010 en 211 duizend op 1-1-2016$$,
   $$wiskunde-b-havo-2026-ii-autos-in-nederland-context3.png$$,
   $$Bij deze auto’s zijn ook elektrische auto’s. Het aantal elektrische auto’s is tussen 2010 en 2016 bij benadering exponentieel gegroeid: − Op 1 januari 2010 waren er 40 duizend elektrische auto’s. − Op 1 januari 2016 was dit aantal 211 duizend.$$, 'inline'),
  ('024b674d-10db-4f25-8734-df8e28f689ff', 'e4ece13c-13a3-4935-9044-1e6afeff400e', $$uitspraak: op 1 januari 2027 is bijna de helft van de auto's elektrisch$$,
   $$wiskunde-b-havo-2026-ii-autos-in-nederland-context4.png$$,
   $$Iemand doet in 2016 de volgende uitspraak: “Als het totale aantal auto’s lineair blijft toenemen en het aantal elektrische auto’s exponentieel blijft toenemen, dan is op 1 januari 2027 bijna de helft van de auto’s in Nederland elektrisch.”$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('b12a991d-12be-4409-8e39-1d9cfb6779cc', '93ba51fd-ec93-469a-a58e-27c67497ce68', 1,
   '[{"domain": "Toegepaste analyse", "subdomain": "Bepaling afgeleide functies"}, {"domain": "Toegepaste analyse", "subdomain": "Toepassing afgeleide functies"}]'::jsonb,
   '["kettingregel", "afgeleide", "raaklijn opstellen", "wortelfunctie", "exact berekenen"]'::jsonb,
   $$Met de kettingregel de afgeleide van een wortelfunctie bepalen en de vergelijking van een raaklijn opstellen.$$,
   $$wiskunde-b-havo-2026-ii-door-punt-p-vraag1.png$$, $$4p 1 Stel op exacte wijze een vergelijking op van lijn k.$$, array['a58c6c61-67be-4966-96eb-79c714935836']::uuid[]),
  ('75c8e1f4-d849-404f-a088-1c1e0bbd4161', '93ba51fd-ec93-469a-a58e-27c67497ce68', 2,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Standaardfuncties"}, {"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Vergelijkingen en ongelijkheden"}]'::jsonb,
   '["randpunt", "top van parabool", "topformule", "kwadratische functie", "exact berekenen"]'::jsonb,
   $$Het randpunt van een wortelfunctie bepalen en daarmee het functievoorschrift van een parabool opstellen.$$,
   $$wiskunde-b-havo-2026-ii-door-punt-p-vraag2.png$$, $$3p 2 Stel op exacte wijze een functievoorschrift op van g.$$, array['a58c6c61-67be-4966-96eb-79c714935836', 'fa5e2c3e-4441-4890-bb68-22b28c4940ea']::uuid[]),
  ('d34cc13f-66b7-41a3-83a9-b965c001a403', 'ebb0b6c0-fc21-49ae-be74-4b73ae70855b', 3,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Periodieke functies"}, {"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Vergelijkingen en ongelijkheden"}]'::jsonb,
   '["goniometrische vergelijking", "periode", "nulpunten sinusoïde", "exacte waarden", "exact berekenen"]'::jsonb,
   $$Een goniometrische vergelijking exact oplossen en de verhouding van twee lijnstukken bij een sinusoïde berekenen.$$,
   $$wiskunde-b-havo-2026-ii-twee-sinusoiden-vraag3.png$$, $$5p 3 Bereken exact hoeveel keer zo lang.$$, array['56e0653b-6834-4fc7-97b1-507e8ac03566']::uuid[]),
  ('f7fbb3fd-29d3-4c31-b7f9-5c26a106d32d', 'ebb0b6c0-fc21-49ae-be74-4b73ae70855b', 4,
   '[{"domain": "Toegepaste analyse", "subdomain": "Veranderingen"}, {"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Periodieke functies"}]'::jsonb,
   '["differentiequotiënt", "helling", "sinusoïde", "vergelijking oplossen", "afronden"]'::jsonb,
